WITH gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM web_events), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT DATE_TRUNC('YEAR', event_time) AS year_start, ROUND(SUM(is_new_session) / NULLIF(COUNT(CASE WHEN page = '/checkout' THEN 1 END), 0), 2) AS is_new_session_per_checkout, APPROX_PERCENTILE(island_id, 0.5) AS island_id_p50 FROM islands GROUP BY DATE_TRUNC('YEAR', event_time) ORDER BY island_id_p50 NULLS LAST;
